# Hutulet (Carpathia No. 10127) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py); the game has no sculptor for it, so its export is a body generated by rule and only its bones,
# clips and size are kept:
#   blender --background --factory-startup --python sculpts/hutulet.py -- <the export's Hutulet.glb> <out.glb>
#
# From the picture (docs/art/reference/gemini/carpathia/10127-Hutulet.jpg) and the brief (CP-dex-3, "127. Hutulet"):
# a sturdy, shaggy mountain foal in bay brown; a big head as wide as the body; a thick black mane in heavy locks, a
# forelock falling over the forehead and long locks hanging beside the cheeks; brown ears with a paler lining standing
# out of the mane; small dark eyes with a glint; a dark grey muzzle with two nostrils and an open, cheerful smile with
# a pink tongue; a shaggy chest; a dark stripe down the spine; short thick legs, black from the knee down, shaggy at the
# fetlock, over dark grey hooves; a bushy black tail hanging back and down and curling up at its end; a woven red
# blanket over the back with white zigzag bands and a fringe of tassels.
#
# Written to be grown from (hutulmare.py takes the palette, the locks, the hooves, the drape and the face through
# sibling("hutulet")); the calls that build Hutulet are under __main__.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import (Kit, ell, tube, blade, lathe, sheet, lumpy, srgb, inside, unit, polygon, eye_look, outward, tri,
                       args)

# --- the line's colours ---------------------------------------------------------------------------------------------
BAY, BAY_DARK, BAY_PALE = "#7C4026", "#4A2416", "#9A5A38"
MANE, SOCK, HOOF = "#1B191C", "#272023", "#45403F"
MUZZLE, NOSTRIL, MOUTH, TONGUE = "#5C5050", "#241C1E", "#3A1C1E", "#E28A8C"
EAR_IN = "#B98266"
RED, CREAM, BLACK = "#A6302B", "#F0E6D6", "#1E1A1C"
IRIS, PUPIL, GLINT = srgb("#3A2216"), srgb("#100A08"), np.array([1.0, 1.0, 1.0])


def at_surface(C, R, d):
    """The point of an ellipsoid (centre C, radii R) in a direction d from its centre."""
    d = np.array(d, float)
    return np.array(C, float) + d / np.linalg.norm(d / np.array(R, float))


def lock(pts, r0, tip=0.3, axis=None, f=1.0, floor=0.0095):
    """A thick tapered lock of mane through points, round at its root and narrowing to a pointed tip (never under
    floor), flattened across axis by f (1 round) so it lies on what it falls over; wound outward."""
    n = len(pts)
    radii = [max(floor, r0 * (1 - (1 - tip) * (i / (n - 1)) ** 1.1)) for i in range(n)]
    if axis is None or f >= 1.0:
        return outward(tube(pts, radii, seg=14, per=6))
    return outward(blade(pts, radii, axis, f))


def hoof(k, x, y, r, h, bone, color=HOOF):
    """A dark hoof: a low drum, a little wider at the foot, its front rounded."""
    k.add("hoof", lathe((x, y, 0.0), (0, 0, 1), [(0, 0), (r, 0), (r * 1.02, h * 0.35), (r * 0.9, h), (0, h)]),
          color, bone, fuse=False, mirror=True, surface="shell")


def drape(cz, rad, y0, y1, phi):
    """at(u, v) of a cloth over a round back: u 0..1 across from one side's hem to the other's (phi radians either
    side of the top), v 0..1 from y0 to y1; rad(y) the cloth's distance from the axis through (0, y, cz)."""
    def at(u, v):
        a = (2 * u - 1) * phi
        y = y0 + (y1 - y0) * v
        r = rad(y)
        return np.stack([r * np.sin(a), y, cz + r * np.cos(a)], axis=-1)
    return at


def band(at_cloth, u0, w, amp=0.0, n=4, nu=7, nv=90):
    """A strip across a cloth's v (a woven band): u0 its middle in u, w its width, amp a zigzag's swing in u."""
    def at(u, v):
        uu = u0 + w * (u - 0.5) + amp * tri(v * n)
        return at_cloth(uu, 0.01 + 0.98 * v)
    return at


def open_eye(u, v):
    """The open eye: a dark brown iris almost to the edge, a black pupil toward the front and a white glint."""
    r = np.sqrt(u * u + v * v)
    c = np.tile(IRIS, (len(u), 1))
    c[r > 0.9] = PUPIL
    c[((u + 0.12) / 0.5) ** 2 + ((v + 0.02) / 0.62) ** 2 < 1] = PUPIL
    c[np.hypot(u + 0.18, v - 0.3) < 0.2] = GLINT
    c[np.hypot(u - 0.22, v + 0.34) < 0.08] = GLINT
    return c


def lay_eyes(k, E, d, half, lid):
    def eyes(state):
        k.decal(E, d, half, eye_look(state, open_eye, srgb(lid), PUPIL, line=0.17), up=unit(0, 0.2, 1),
                eps=0.004, rings=20, segs=56, mirror=True)
    return eyes


def face(k, MZ, MR, s=1.0, smile=True):
    """Two nostrils at the muzzle's front and, under them, the open smile with its pink tongue."""
    for sx in (1, -1):
        dn = unit(0.42 * sx, -1, 0.25)
        k.decal(at_surface(MZ, MR, dn), dn, (0.013 * s, 0.017 * s), NOSTRIL, up=unit(-0.3 * sx, 0, 1), eps=0.003,
                rings=8, segs=40)
    if smile:
        dm = unit(0, -0.72, -0.62)
        def mouth(u, v):
            c = np.tile(srgb(MOUTH), (len(u), 1))
            c[(u / 0.62) ** 2 + ((v + 0.45) / 0.42) ** 2 < 1] = srgb(TONGUE)
            return c
        k.decal(at_surface(MZ, MR, dm), dm, (0.05 * s, 0.03 * s), mouth, up=unit(0, -0.6, 1), eps=0.003,
                outline=polygon([(-1, 0.45), (-0.5, 0.25), (0, 0.18), (0.5, 0.25), (1, 0.45), (0.8, -0.1),
                                 (0.42, -0.6), (0, -0.82), (-0.42, -0.6), (-0.8, -0.1)]), rings=12, segs=64)
    else:
        dm = unit(0, -0.72, -0.62)
        k.decal(at_surface(MZ, MR, dm), dm, (0.05 * s, 0.009 * s), MOUTH, up=unit(0, -0.6, 1), eps=0.003,
                outline=polygon([(-1, 0.6), (0, -0.2), (1, 0.6), (0.9, 1.0), (0, 0.6), (-0.9, 1.0)]), rings=8, segs=48)


def mane(k):
    """Hutulet's mane: pointed, flattened locks of uneven length whose tips lift clear of the mass."""
    hair = []
    for x, zt in ((-0.036, 0.505), (-0.012, 0.485), (0.014, 0.515), (0.04, 0.495)):    # the forelock
        a = np.array([x, -0.28, 0.61])
        hair.append(([a, (x * 1.1, -0.35, 0.603), (x * 1.2, -0.395, 0.56), (x * 1.25, -0.415, zt)], 0.04,
                     unit(0, -1, 0.3)))
    for sx in (1, -1):
        for j, (dy, dz) in enumerate(((0.0, 0.0), (0.045, 0.02))):      # beside the cheeks, behind the eyes
            a = np.array([0.085 * sx, -0.27 + dy, 0.59 + dz])
            hair.append(([a, (0.125 * sx, -0.285 + dy, 0.52), (0.135 * sx, -0.29 + dy, 0.45),
                          (0.155 * sx, -0.30 + dy, 0.385 - 0.025 * j)], 0.036, (1, 0, 0)))
        a = np.array([0.055 * sx, -0.25, 0.612])                          # over the crown, beside the ears
        hair.append(([a, (0.1 * sx, -0.235, 0.6), (0.14 * sx, -0.23, 0.55), (0.165 * sx, -0.22, 0.505)], 0.034,
                     unit(0.6 * sx, 0, 0.8)))
    for i, (t, L) in enumerate(zip(np.linspace(0, 1, 6), (0.2, 0.18, 0.2, 0.165, 0.15, 0.12))):  # the crest
        a = np.array([0, -0.22, 0.6]) * (1 - t) + np.array([0, -0.05, 0.445]) * t
        for sx in (1, -1):
            L2 = L * (0.9 if (i + (sx > 0)) % 2 else 1.05)
            d = unit(0.45 * sx, 0.2 + 0.1 * (i % 2), -0.87)
            hair.append(([a, a + d * L2 * 0.45 + (0, 0, 0.016), a + d * L2 * 0.85,
                          a + d * L2 + (0.035 * sx, 0.01, 0.01)], 0.046, unit(0.8 * sx, 0, 0.55)))
    # the crest's own mass, which the locks fall from, so the mane reads as one thick mane from behind
    crest = [np.array(p, float) for p in ((0, -0.27, 0.615), (0, -0.2, 0.592), (0, -0.12, 0.535), (0, -0.04, 0.45))]
    k.add("manecore", lock(crest, 0.052, 0.6), MANE, "head", fuse=False, surface="hair")
    for i, (pts, r, ax) in enumerate(hair):
        bone = "head" if pts[0][1] < -0.12 else "body"
        k.add(f"mane{i}", lock([np.array(p, float) for p in pts], r, 0.2, ax, 0.55), MANE, bone, fuse=False,
              surface="hair")


def tail(k, TB, s=1.0, drop=0.24, color=MANE):
    """A bushy tail: one thick lock hanging back and down from TB with six more about it whose tips flick out."""
    path = [np.array(p, float) for p in ((0, -0.01, 0.02), (0.02, 0.09, -0.05), (0.05, 0.15, -0.15),
                                         (0.08, 0.18, -drop / s))]
    k.add("tailroot", ell(TB, (0.045 * s, 0.045 * s, 0.045 * s)), color, "tail")
    k.add("tailcore", lock([TB + p * s for p in path], 0.055 * s, 0.55), color, "tail", fuse=False, surface="hair")
    for i, (ox, oz, r) in enumerate([(0.05, 0.02, 0.036), (-0.045, 0.02, 0.034), (0.04, -0.03, 0.034),
                                     (-0.03, -0.035, 0.032), (0.065, -0.005, 0.03), (0.0, 0.05, 0.03)]):
        off = np.array([ox, 0, oz])
        pts = [TB + (path[0] + off * 0.2) * s, TB + (path[1] + off * 0.6) * s, TB + (path[2] + off) * s,
               TB + (path[3] + off * 1.5 + (0.015, 0.03, 0.012)) * s]
        k.add(f"tail{i}", lock(pts, r * s, 0.3), color, "tail", fuse=False, surface="hair")


def hutulet(src, out):
    k = Kit(src, coat="fur")

    # --- the trunk: a deep round barrel, chest and rump, the belly a quarter of the height off the ground ---------
    k.add("barrel", ell((0, 0.03, 0.30), (0.13, 0.22, 0.132)), BAY, "body")
    k.add("chest", ell((0, -0.14, 0.312), (0.128, 0.12, 0.138), deform=lumpy(9, 5, 0.05)), BAY, "body")
    k.add("rump", ell((0, 0.18, 0.31), (0.126, 0.12, 0.128)), BAY, "body")
    # shoulders and haunches fused over the legs' tops, the legs short and thick under them
    k.add("shoulder", ell((0.088, -0.15, 0.25), (0.06, 0.078, 0.1)), BAY, "leg{s}", mirror=True)
    k.add("thigh", ell((0.088, 0.17, 0.26), (0.066, 0.088, 0.1)), BAY, "hind{s}", mirror=True)
    for nm, y, bone in (("fore", -0.16, "leg{s}"), ("hind", 0.165, "hind{s}")):
        k.add(nm, tube([(0.09, y, 0.24), (0.09, y - 0.004, 0.14), (0.09, y - 0.008, 0.05)], [0.054, 0.048, 0.047]),
              BAY, bone, mirror=True)
        # the fetlock's shaggy black cuff
        k.add(nm + "cuff", ell((0.09, y - 0.01, 0.068), (0.062, 0.064, 0.042), deform=lumpy(5, 2, 0.12)), SOCK,
              bone, mirror=True)
        hoof(k, 0.09, y - 0.012, 0.054, 0.05, bone)

    # --- the neck and the big head, as wide as the body; the dark muzzle ----------------------------------------
    k.add("neck", tube([(0, -0.17, 0.36), (0, -0.22, 0.42), (0, -0.25, 0.47)], [0.1, 0.092, 0.088]), BAY, "head")
    H, HR = np.array([0, -0.27, 0.495]), np.array([0.112, 0.11, 0.106])
    k.add("head", ell(H, HR), BAY, "head")
    MZ, MR = np.array([0, -0.37, 0.425]), np.array([0.076, 0.082, 0.07])
    k.add("muzzle", ell(MZ, MR), MUZZLE, "head", surface="skin")
    k.add("snout", ell((0, -0.33, 0.45), (0.084, 0.06, 0.07)), BAY, "head")
    face(k, MZ, MR, 1.12)

    # --- ears standing out of the mane, brown with a pale lining --------------------------------------------------
    EB, ET = np.array([0.062, -0.285, 0.57]), np.array([0.088, -0.29, 0.64])
    k.add("ear", tube([EB, (EB + ET) / 2 + (0.006, -0.006, 0), ET], [0.03, 0.03, 0.01]), BAY, "ear{s}",
          mirror=True)
    k.decal((EB + ET) / 2 + (0.004, -0.024, -0.004), unit(0.2, -1, 0.1), (0.014, 0.024), EAR_IN,
            up=unit(0.3, 0, 1), eps=0.003, rings=8, segs=40, mirror=True)

    # --- the mane: a forelock over the forehead, long locks beside the cheeks, heavy locks down the neck ---------
    mane(k)
    # --- the tail: a bushy black broom hanging back and down, its tips flicking out toward +X -----------------
    tail(k, np.array((0, 0.27, 0.39)), 1.0)

    # --- the dark stripe down the spine ---------------------------------------------------------------------------
    k.paint(lambda P: inside(np.abs(P[:, 0]) - 0.024, 0.004) * (P[:, 2] > 0.36) * (P[:, 1] > -0.2) * (P[:, 1] < 0.3),
            BAY_DARK, on=["barrel", "chest", "rump"])
    # the legs black from the knee down
    k.paint(lambda P: inside(P[:, 2] - 0.15, 0.006) * (P[:, 2] < 0.2), SOCK)
    # a little paler under the belly and on the chest's front
    k.paint(lambda P: inside(P[:, 2] - 0.2, 0.02) * (P[:, 2] > 0.14) * (np.abs(P[:, 0]) < 0.07), BAY_PALE,
            on=["barrel", "chest", "rump"])

    # --- the woven blanket over the back: red cloth, white zigzag bands and a white hem, a fringe of tassels -----
    rad = lambda y: 0.142 + 0.0 * y
    cloth = drape(0.3, rad, -0.07, 0.13, math.radians(102))
    k.add("blanket", outward(sheet(cloth, 41, 21, 0.01)), RED, "body", fuse=False, surface="cloth")
    lift = drape(0.3, lambda y: rad(y) + 0.002, -0.07, 0.13, math.radians(102))
    for i, (u0, w, amp) in enumerate([(0.06, 0.05, 0.0), (0.94, 0.05, 0.0), (0.24, 0.035, 0.035),
                                      (0.76, 0.035, 0.035), (0.5, 0.035, 0.03)]):
        k.add(f"weave{i}", outward(sheet(band(lift, u0, w, amp, 5), 7, 90, 0.016)), CREAM, "body", fuse=False,
              surface="cloth")
    # the black edge along the ends of the cloth
    for i, v0 in enumerate((0.0, 1.0)):
        def edge(u, v, v0=v0):
            return lift(0.015 + 0.97 * u, 0.002 + 0.03 * v if v0 == 0 else 0.968 + 0.03 * v)
        k.add(f"selvage{i}", outward(sheet(edge, 60, 3, 0.016)), BLACK, "body", fuse=False, surface="cloth")
    # tassels along both hems
    for sx in (1, -1):
        for j, v in enumerate(np.linspace(0.06, 0.94, 6)):
            p = cloth(np.array(1.0 if sx > 0 else 0.0), np.array(v))
            p = np.array(p, float) + (0.006 * sx, 0, 0.004)
            col = CREAM if j % 2 else RED
            k.add(f"tassel{'RL'[sx < 0]}{j}", lock([p, p + (0.006 * sx, 0, -0.025), p + (0.008 * sx, 0, -0.045)],
                                                   0.011, 0.6), col, "body", fuse=False, surface="cloth")

    # --- the eyes: small and dark, high on the head's sides, a little forward -----------------------------------
    de = unit(0.64, -0.66, 0.36)
    E = at_surface(H, HR, de)
    k.build(voxel=0.0062, smooth=4, band=0.008)
    k.eye_states(lay_eyes(k, E, de, (0.026, 0.03), BAY))
    k.export(out)


if __name__ == "__main__":
    hutulet(*args())
